import{f as t,c as r,o as a,aq as n}from"./chunks/framework.CWvjhqVd.js";const i="/Wahllokalsystem/developmentPCEnvironment.png",b=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"technik/get_started/index.md","filePath":"technik/get_started/index.md"}'),d={name:"technik/get_started/index.md"};function s(o,e,l,c,h,u){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><h2 id="formatter-einrichten" tabindex="-1">Formatter einrichten <a class="header-anchor" href="#formatter-einrichten" aria-label="Permalink to &quot;Formatter einrichten&quot;">​</a></h2><p>Im Projekt verwenden wir <code>checkstyle</code> und <code>spotless</code> um für einen möglichst einheitlichen Codestyle zu sorgen. Dazu haben wir Regeln definiert. Diese Regeln und deren Hinterlegung in der jeweiligen IDE ist <a href="https://github.com/it-at-m/itm-java-codeformat" target="_blank" rel="noreferrer">hier</a> beschrieben.</p><h2 id="zusammenspiel-ide-mit-podman" tabindex="-1">Zusammenspiel IDE mit Podman <a class="header-anchor" href="#zusammenspiel-ide-mit-podman" aria-label="Permalink to &quot;Zusammenspiel IDE mit Podman&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">Konfiguration von hosts</p><p></p><p>Im hosts-File müssen folgende Enträge enthalten sein, damit das Wahllokalsystem lokal korrekt funktioniert 127.0.0.1 host.docker.internal 127.0.0.1 auth.wls.host.docker.internal 127.0.0.1 gui.wls.host.docker.internal</p></div><p><img src="'+i+'" alt="Aufteilung Komponenten auf dem Entwicklungs-PC"></p><p>Auf dem Entwicklungs-PC müssen Container ausführbar sein. Einige Komponenten, die zur Ausführung des Systems notwendig sind, liegen nur als Image vor. Die Komponenten sind mit <code>podman only</code> markiert. Alle anderen Komponenten liegen sowohl als Image als auch anderweitig startbar vor. Die Microservices können über Skripte oder <code>Run Configurations</code> (IntelliJ) ausgeführt werden.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>Damit Services, die in Podman laufen, mit Services außerhalb von Podman kommunizieren können, müssen die Container das entsprechende Host-Gateway konfiguriert haben.</p></div><div class="caution custom-block github-alert"><p class="custom-block-title">Zugriff bei Frontendentwicklung</p><p></p><p>Bei der Entwicklung am Frontend sollte der Zugriff über <code>host.docker.internal:8083</code> erfolgen, da nur dadurch das Hot Module Replacement (HMR) des Vite-Servers funktioniert. Bei Zugriff über <code>gui.wls.host.docker.internal:58083</code> kann die WebSocket-Verbindung nicht aufgebaut werden, und HMR funktioniert nicht.</p></div><h2 id="services-und-ports" tabindex="-1">Services und Ports <a class="header-anchor" href="#services-und-ports" aria-label="Permalink to &quot;Services und Ports&quot;">​</a></h2><p>Übersicht über die Services und auf welchen Port sie im Standard lauschen:</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Diese Ports werden sowohl in der IDE als auch in Podman verwendet. Beachten Sie, dass somit nur eine Instanz eines Services gleichzeitig laufen kann.</p></div><table tabindex="0"><thead><tr><th>Service</th><th>Port</th></tr></thead><tbody><tr><td><a href="/Wahllokalsystem/services/backend-services/admin-service/">Admin</a></td><td>8209</td></tr><tr><td><a href="/Wahllokalsystem/services/backend-services/auth-service/">Auth</a></td><td>8100</td></tr><tr><td><a href="/Wahllokalsystem/services/backend-services/basisdaten-service/">Basisdaten</a></td><td>8205</td></tr><tr><td><a href="/Wahllokalsystem/services/backend-services/briefwahl-service/">Briefwahl</a></td><td>8202</td></tr><tr><td><a href="/Wahllokalsystem/services/backend-services/broadcast-service/">Broadcast</a></td><td>8200</td></tr><tr><td><a href="/Wahllokalsystem/services/backend-services/eai-service/">EAI</a></td><td>8300</td></tr><tr><td><a href="/Wahllokalsystem/services/backend-services/ergebnismeldung-service/">Ergebnismeldung</a></td><td>8208</td></tr><tr><td><a href="/Wahllokalsystem/services/backend-services/infomanagement-service/">Infomanagement</a></td><td>8201</td></tr><tr><td><a href="/Wahllokalsystem/services/backend-services/monitoring-service/">Monitoring</a></td><td>8206</td></tr><tr><td><a href="/Wahllokalsystem/services/backend-services/vorfaelleundvorkommnisse-service/">Vorfälle und Vorkommnisse</a></td><td>8204</td></tr><tr><td><a href="/Wahllokalsystem/services/backend-services/wahlvorbereitungs-service/">Wahlvorbereitung</a></td><td>8203</td></tr><tr><td><a href="/Wahllokalsystem/services/backend-services/wahlvorstand-service/">Wahlvorstand</a></td><td>8207</td></tr></tbody></table><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Profilname</th><th>Beschreibung</th></tr></thead><tbody><tr><td>db-h2</td><td>Als Datenbank wird eine embedded H2 im Service verwendet.</td></tr><tr><td>db-oracle</td><td>Als Datenbank wird eine Oracle Datenbank verwendet. Im Standard wird die DB-Datenbank aus dem Stack (Podman) verwendet.</td></tr><tr><td>db-dummydata</td><td>Es werden Flyway-Files mit Dummydaten für die Datenbank mit verwendet.</td></tr><tr><td>no-security</td><td>Die Prüfungen der Authentifizierung und Authorisierung werden deaktiviert.</td></tr><tr><td>dummy.nobezirkid.check</td><td>Deaktiviert die Prüfung, dass Anfragen für einen bestimmten Wahlbezirk (wahlbezirkID), nur von dem User des Wahlbezirkes erfolgen dürfen</td></tr><tr><td>dummy.clients</td><td>Es erfolgt keine Kommunikation mit fachlichen Services weil Dummy-Implementierung anstatt von Clients verwendet werden.</td></tr><tr><td>standalone</td><td>Der Service arbeitet eigenständig. Inkludiert dummy.clients, dummy.nobezirkid.check und db-h2.</td></tr><tr><td>local</td><td>Der Service läuft lokal. Entsprechend wird der Port des Services definiert um nicht in Konflikt mit anderen Service zu kommen.</td></tr><tr><td>plainTextLogging</td><td>Logmeldungen werden als Text ausgegeben. Ohne dieses Profil sind die Logmeldungen ein JSON-Objekt.</td></tr></tbody></table><h2 id="benutzer" tabindex="-1">Benutzer <a class="header-anchor" href="#benutzer" aria-label="Permalink to &quot;Benutzer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Passwort</th><th>Beschreibung</th></tr></thead><tbody><tr><td>wls_all_bwb</td><td>test</td><td>Ein Benutzer mit der Rolle Monitoring_Helpdesk für das Admintool</td></tr><tr><td>wls_all_uwb</td><td>test</td><td>Ein Benutzer mit der Rolle Monitoring_Helpdesk für das Admintool</td></tr><tr><td>wls_komw_bwb</td><td>test</td><td>Ein Benutzer mit der Rolle Wahlvorstand für eine Kommunalwahl mit OBW und SRW sowie der WahlbezirksArt BWB (Briefwahl)</td></tr><tr><td>wls_komw_uwb</td><td>test</td><td>Ein Benutzer mit der Rolle Wahlvorstand für eine Kommunalwahl mit OBW und SRW sowie der WahlbezirksArt UWB (Urnenwahl)</td></tr><tr><td>wls_mbw_bwb</td><td>test</td><td>Ein Benutzer mit der Rolle Wahlvorstand für eine Migrationsbeiratswahl und der WahlbezirksArt BWB (Briefwahl)</td></tr><tr><td>wls_mbw_uwb</td><td>test</td><td>Ein Benutzer mit der Rolle Wahlvorstand für eine Migrationsbeiratswahl und der WahlbezirksArt UWB (Urnenwahl)</td></tr></tbody></table><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Für die Anmeldung am WLS muss der User die Rolle <code>WLS_WAHLVORSTAND</code> haben. Für die Anmeldung am Admintool muss der User die Rolle <code>MONITORING_HELPDESK</code> haben.</p></div><h2 id="datenbank" tabindex="-1">Datenbank <a class="header-anchor" href="#datenbank" aria-label="Permalink to &quot;Datenbank&quot;">​</a></h2><p>Der Zugriff auf die Oracle-Datenbank über die IDE ist gemäß <a href="/Wahllokalsystem/technik/guides/db-access.html">dieser Anleitung</a> einzurichten.</p><h2 id="runconfigurations" tabindex="-1">Runconfigurations <a class="header-anchor" href="#runconfigurations" aria-label="Permalink to &quot;Runconfigurations&quot;">​</a></h2><p>Für die Spring-Boot Microservices werden für IntelliJ Runconfigurations zur Verfügung gestellt. Diese sind gruppiert nach der Art der Datenbank und ob die Security aktiviert ist oder nicht.</p><p>Eine Übersicht über die Profile gibt es <a href="#profile">hier</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Wenn es Updates an den Runconfigurations gab, die gefetcht wurden, ist es notwendig IntelliJ neu zu starten.</p></div><h2 id="podman" tabindex="-1">Podman <a class="header-anchor" href="#podman" aria-label="Permalink to &quot;Podman&quot;">​</a></h2><p>Für die Nutzung von Podman ist im <code>docker-compose.yml</code> File <code>host.docker.internal</code> als DNS-Name konfiguriert, damit die Kommunikation zwischen Containern und dem Host-Computer vereinfacht wird. Dabei ist darauf zu achten, dass im <code>hosts</code> File unter <code>C:\\Windows\\System32\\drivers\\etc</code> der folgende Eintrag existiert, sodass <code>host.docker.internal</code> auf <code>localhost</code> verweist:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>127.0.0.1 host.docker.internal</span></span></code></pre></div><h2 id="starten-des-frontends" tabindex="-1">Starten des Frontends <a class="header-anchor" href="#starten-des-frontends" aria-label="Permalink to &quot;Starten des Frontends&quot;">​</a></h2><p>Standardmäßig wird das Frontend über den Befehl <code>&quot;dev&quot;: &quot;vite&quot;</code> in der <code>package.json</code>-Datei gestartet.</p><p>Nachdem das Frontend in der IDE und das ApiGateway über Podman gestartet wurde, kann es über <code>http://localhost:8400/</code> aufgerufen werden. Allerdings befindet sich die Oberfläche dann in einer Ladeschleife und man sieht nur einen flackernden Bildschirm. Um diese Schleife während der Entwicklung zu umgehen, gibt es zwei Möglichkeiten:</p><h3 id="start-via-gateway" tabindex="-1">1. Starten über das Gateway + Authentifizierung <a class="header-anchor" href="#start-via-gateway" aria-label="Permalink to &quot;1. Starten über das Gateway + Authentifizierung {#start-via-gateway}&quot;">​</a></h3><p>Eine Möglichkeit, die Ladeschleife zu umgehen, ist es, sich lokal mit einem der <a href="#benutzer">User</a> anzumelden. Nachdem das Frontend über die IDE gestartet wurde, muss die URL <code>http://localhost:8083/</code> mit dem Port <code>8083</code> aufgerufen werden, um auf die Login-Seite zu kommen. Nach der Anmeldung bleibt man auf dem Port <code>8083</code>, wird aber vom Gateway zum Frontend weitergeleitet und die Ladeschleife ist weg.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Der Anmeldevorgang muss jedes Mal wiederholt werden, sobald das ApiGateway neu gestartet wird.</p></div><h3 id="_2-no-security-profil" tabindex="-1">2. <code>no-security</code>-Profil <a class="header-anchor" href="#_2-no-security-profil" aria-label="Permalink to &quot;2. `no-security`-Profil&quot;">​</a></h3><p>Die zweite Möglichkeit ist es, das ApiGateway mit dem <code>no-security</code>-Profil zu starten. Dazu muss im <code>/stack/docker-compose.yml</code> File beim Service refarch-gateway unter environment in der Zeile <code>- SPRING_PROFILES_ACTIVE=hazelcast-local</code> das Profil <code>no-security</code> hinzugefügt werden. Damit die Änderung wirksam wird, sollte der Container in Podman einmal komplett gelöscht und über das <code>docker-compose.yml</code> File neu gestartet werden.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Bei dieser Variante ist es wichtig, dass die Änderung im <code>docker-compose.yml</code> File nicht gepusht wird, weil alle anderen Container mit security laufen und das <code>no-security</code>-Profil nur für die Entwicklung benötigt wird.</p></div><h3 id="backend-services" tabindex="-1">Backend-Services <a class="header-anchor" href="#backend-services" aria-label="Permalink to &quot;Backend-Services&quot;">​</a></h3><p>Damit das Frontend im Zusammenspiel mit den anderen Services lokal gestartet werden kann, sind einmalig nach dem Aufsetzen der DB folgende Schritte notwendig:</p><ol><li><code>db-oracle</code>-Service in Podman oder über das <code>docker-compose.yml</code> starten</li><li><code>auth-service</code> starten</li><li><code>refarch-gateway-wls</code>-Service in Podman oder über das <code>docker-compose.yml</code> starten</li><li>Das Wahllokalsystem-Frontend in Podman oder über <code>npm run dev</code> starten (siehe <a href="#start-via-gateway">Punkt 1</a>: <em>Jetzt kann das Frontend zwar aufgerufen werden, aber durch das fehlgeschlagene Laden der initialen Daten ist noch kein Zugriff auf die Anwendung möglich)</em></li><li>die Services <code>basisdaten-service</code>, <code>eai-service</code>, <code>ergebnismeldung-service</code>, <code>infomanagement-service</code> und <code>wahlvorstand-service</code> starten und die http-requests aus dem File für die gewünschte Wahl ausführen (Kommunalwahl mit OBW und SRW: <a href="https://github.com/it-at-m/Wahllokalsystem/blob/dev/stack/http_requests/initOracleDB_Komw.http" target="_blank" rel="noreferrer"><code>initOracleDB_KomW.http</code></a> oder Migrationsbeiratswahl: <a href="https://github.com/it-at-m/Wahllokalsystem/blob/dev/stack/http_requests/initOracleDB_MBW.http" target="_blank" rel="noreferrer"><code>initOracleDB_MBW.http</code></a>)</li></ol>',39)])])}const g=t(d,[["render",s]]);export{b as __pageData,g as default};
